WITH flattened_attrs AS (SELECT id, plan, currency, tier_limits, SLICE(tier_limits, 1, 2) AS first_two_limits, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ELEMENT_AT(tier_prices, 1) AS entry_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers) SELECT CASE WHEN entry_price >= 25 THEN 'LARGE' ELSE 'SMALL' END AS entry_price_tier, currency, MIN(entry_price) AS min_entry_price, COUNT(*) FILTER (WHERE plan = 'pro') AS pro_rows, APPROX_PERCENTILE(lowest_price, 0.5) AS lowest_price_p50, APPROX_PERCENTILE(lowest_price, ARRAY(0.25, 0.5, 0.75)) AS lowest_price_quartiles FROM flattened_attrs GROUP BY 1, 2;
